import java.io.*;
import java.util.*;

class Solution {
    public int maxBuilding(int n, int[][] restrictions) {
        int m = restrictions.length;
        int[][] rs = new int[m + 2][2];
        for (int i = 0; i < m; i++) {
            rs[i][0] = restrictions[i][0];
            rs[i][1] = restrictions[i][1];
        }
        rs[m][0] = 1; rs[m][1] = 0;
        rs[m + 1][0] = n; rs[m + 1][1] = n - 1;
        Arrays.sort(rs, (a, b) -> Integer.compare(a[0], b[0]));
        for (int i = rs.length - 2; i >= 0; --i)
            rs[i][1] = Math.min(rs[i][1], rs[i + 1][1] + rs[i + 1][0] - rs[i][0]);
        int ans = 0;
        for (int i = 1; i < rs.length; ++i) {
            rs[i][1] = Math.min(rs[i][1], rs[i - 1][1] + rs[i][0] - rs[i - 1][0]);
            int left = rs[i - 1][0], h1 = rs[i - 1][1];
            int right = rs[i][0], h2 = rs[i][1];
            ans = Math.max(ans, Math.max(h1, h2) + (right - left - Math.abs(h1 - h2)) / 2);
        }
        return ans;
    }
}

