typedef struct { char *s; size_t p, len; } Parser;

static void ws(Parser *p) { while (p->p < p->len && (p->s[p->p]==' '||p->s[p->p]=='\n'||p->s[p->p]=='\r'||p->s[p->p]=='\t'||p->s[p->p]==',')) p->p++; }
static long next_int(Parser *p) {
    ws(p);
    int sign=1; if (p->p<p->len && p->s[p->p]=='-') { sign=-1; p->p++; }
    long v=0; while(p->p<p->len && p->s[p->p]>='0'&&p->s[p->p]<='9') v=v*10+(p->s[p->p++]-'0');
    return sign*v;
}
typedef struct { int id,h; } RPair;
static int cmp_pair(const void*a,const void*b){ const RPair*x=a,*y=b; return (x->id>y->id)-(x->id<y->id); }
static int maxBuilding(int n, int** restrictions, int restrictionsSize, int* restrictionsColSize) {
    int m=restrictionsSize;
    RPair *rs=malloc((m+2)*sizeof(RPair));
    for(int i=0;i<m;i++){rs[i].id=restrictions[i][0];rs[i].h=restrictions[i][1];}
    rs[m]=(RPair){1,0}; rs[m+1]=(RPair){n,n-1};
    qsort(rs,m+2,sizeof(RPair),cmp_pair);
    for(int i=m;i>=0;i--){int v=rs[i+1].h+rs[i+1].id-rs[i].id;if(v<rs[i].h)rs[i].h=v;}
    int ans=0;
    for(int i=1;i<m+2;i++){
        int v=rs[i-1].h+rs[i].id-rs[i-1].id;if(v<rs[i].h)rs[i].h=v;
        int d=rs[i].id-rs[i-1].id, diff=abs(rs[i].h-rs[i-1].h);
        int peak=(rs[i].h>rs[i-1].h?rs[i].h:rs[i-1].h)+(d-diff)/2;
        if(peak>ans)ans=peak;
    }
    free(rs); return ans;
}

