    static Object[] parse(String s) {
        int p=1; while(s.charAt(p)==' '||s.charAt(p)==',')p++;
        int start=p; while(Character.isDigit(s.charAt(p)))p++;
        int n=Integer.parseInt(s.substring(start,p));
        while(s.charAt(p)!='[')p++; p++;
        ArrayList<int[]> a=new ArrayList<>();
        while(s.charAt(p)!=']') {
            while(s.charAt(p)!='[')p++; p++; while(s.charAt(p)==' ')p++;
            int id=0; while(Character.isDigit(s.charAt(p)))id=id*10+s.charAt(p++)-'0';
            while(s.charAt(p)!=',')p++; p++; while(s.charAt(p)==' ')p++;
            int h=0; while(Character.isDigit(s.charAt(p)))h=h*10+s.charAt(p++)-'0';
            while(s.charAt(p)!=']')p++; p++; a.add(new int[]{id,h});
            while(s.charAt(p)==','||s.charAt(p)==' ')p++;
        }
        return new Object[]{n,a.toArray(new int[0][2])};
